parameters.jsCode:
// Parser l'analyse GPT
const gpt = $input.first().json;
const lead = $('Trouver le Lead').first().json;
const reply = $('Nouvelles Réponses (Gmail)').first().json;

let analysis;
try {
  const content = gpt.message?.content || gpt.choices?.[0]?.message?.content || '{}';
  analysis = JSON.parse(content);
} catch {
  analysis = { intent: 'question', can_auto_reply: false, confidence: 0, escalate_to_human: true };
}

return [{
  json: {
    lead_id: lead.id,
    lead_email: lead.email,
    lead_name: `${lead.first_name} ${lead.last_name}`,
    lead_company: lead.company_name,
    reply_body: reply.text || reply.snippet || '',
    reply_subject: reply.subject || '',
    ...analysis
  }
}];

